window.docContents[78].resolve({"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Evaluation-as-a-Relation--Equivalence-of-the-Definitions":{"contents":"It is straightforward to prove that the relational and functional\ndefinitions of evaluation agree.\n\ntheorem Aexp.evalR_iff_eval (a : Aexp) (n : Nat) :\n    a ⇓ n ↔ a.eval = n := by\n  constructor\n  · intro h\n    induction h with\n    | num n => rfl\n    | plus h₁ h₂ ih₁ ih₂ => simp only [Aexp.eval_plus]; rw [ih₁, ih₂]\n    | minus h₁ h₂ ih₁ ih₂ => simp only [Aexp.eval_minus]; rw [ih₁, ih₂]\n    | mult h₁ h₂ ih₁ ih₂ => simp only [Aexp.eval_mult]; rw [ih₁, ih₂]\n  · intro h\n    subst h\n    induction a with\n    | num n => exact .num n\n    | plus a₁ a₂ ih₁ ih₂ => exact .plus ih₁ ih₂\n    | minus a₁ a₂ ih₁ ih₂ => exact .minus ih₁ ih₂\n    | mult a₁ a₂ ih₁ ih₂ => exact .mult ih₁ ih₂\n\n\nWe can make the proof quite a bit shorter using more automation like we did in\nthe previous section.\n\nthe workinclass! marker should signal this live in-class exercise.\nBut it is not rendering properly on the HTML. In fact it replaces workinclass! with\nthe all_goals tactic, which we don't need.\n\ntheorem Aexp.evalR_iff_eval' (a : Aexp) (n : Nat) :\n    a ⇓ n ↔ a.eval = n := by\n  workinclass!\n    constructor <;> intro h\n    · induction h <;> simp_all\n    · subst h; induction a <;> constructor <;> assumption\n\n\nWrite a relation Bexp.EvalR in the same style as Aexp.EvalR, and prove that\nit is equivalent to Bexp.eval.inductive Bexp.EvalR : Bexp → Bool → Prop where\n  | bool (b : Bool) : EvalR (.bool b) b\n  | eq {a₁ a₂ : Aexp} {n₁ n₂ : Nat} (h₁ : a₁ ⇓ n₁) (h₂ : a₂ ⇓ n₂) : EvalR (.eq a₁ a₂) (n₁ == n₂)\n  | neq {a₁ a₂ : Aexp} {n₁ n₂ : Nat} (h₁ : a₁ ⇓ n₁) (h₂ : a₂ ⇓ n₂) : EvalR (.neq a₁ a₂) (n₁ != n₂)\n  | le {a₁ a₂ : Aexp} {n₁ n₂ : Nat} (h₁ : a₁ ⇓ n₁) (h₂ : a₂ ⇓ n₂) : EvalR (.le a₁ a₂) (n₁ ≤ n₂)\n  | gt {a₁ a₂ : Aexp} {n₁ n₂ : Nat} (h₁ : a₁ ⇓ n₁) (h₂ : a₂ ⇓ n₂) : EvalR (.gt a₁ a₂) (n₁ > n₂)\n  | not {b : Bexp} {bv : Bool} (h : EvalR b bv) : EvalR (.not b) (!bv)\n  | and {b₁ b₂ : Bexp} {bv₁ bv₂ : Bool} (h₁ : EvalR b₁ bv₁) (h₂ : EvalR b₂ bv₂) :\n      EvalR (.and b₁ b₂) (bv₁ && bv₂)\n\nscoped notation:55 e:56 \" ⇓ \" b:56 => Bexp.EvalR e b\ntheorem Bexp.evalR_iff_eval (b : Bexp) (bv : Bool) :\n    b ⇓ bv ↔ b.eval = bv := by\n  solution!\n    constructor <;> intro h\n    · induction h <;> simp_all [Aexp.evalR_iff_eval]\n    · subst h\n      induction b <;> constructor <;> simp_all [Aexp.evalR_iff_eval]\n\n\nend Slang\n\n\n","context":"Type Systems\u0009Slang: Arithmetic and Boolean Expressions\u0009Evaluation as a Relation","header":"2.2.2. Equivalence of the Definitions","id":"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Evaluation-as-a-Relation--Equivalence-of-the-Definitions"}});